// What players call the hero: his name tag, and how Chinese sentences name
// him. The code still says "bobby" everywhere.
const HERO_NAME = "Dr. Beauty";
const HERO_TAG = "DR. BEAUTY";
const HERO_NAME_ZH = "美麗本人";
const TAU = Math.PI * 2;
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const lerp = (a, b, t) => a + (b - a) * t;
const easeInOut = (t) => t * t * (3 - 2 * t);
const approachValue = (current, target, maxDelta) => {
  if (current < target) return Math.min(target, current + maxDelta);
  if (current > target) return Math.max(target, current - maxDelta);
  return target;
};
