const GAME_TITLE = "MASTER OF THE HOUSE";
// Which build is actually in the browser. Read off the script tag's own
// cache-busting query, so it cannot drift from what is loaded, and printed on
// the GAME CREDITS page - the fastest way to tell a stale tab from a real bug.
const BUILD_ID = (() => {
  try {
    // Matched by its cache-busting query rather than its filename: the deploy
    // builder scans this file for asset paths, and a literal script name here
    // reads to it as a missing runtime file.
    const src = [...document.querySelectorAll("script[src]")]
      .map((script) => script.getAttribute("src") || "")
      .find((value) => value.includes("?v=")) || "";
    return new URLSearchParams(src.split("?")[1] || "").get("v") || "dev";
  } catch {
    return "dev";
  }
})();
