  drawFinaleBackstageMap() {
    const stage = this.getFinaleStageConfig();
    const image = this.refs.finaleBackstageMap;
    this.ctx.fillStyle = "#05070d";
    this.ctx.fillRect(0, 0, VIEW_W, VIEW_H);
    if (!image) {
      const wall = this.ctx.createLinearGradient(0, 0, 0, VIEW_H);
      wall.addColorStop(0, "#10151d");
      wall.addColorStop(0.52, "#2b211a");
      wall.addColorStop(1, "#08090d");
      this.ctx.fillStyle = wall;
      this.ctx.fillRect(0, 0, VIEW_W, VIEW_H);
      this.ctx.fillStyle = "#201816";
      this.ctx.fillRect(0, 512, VIEW_W, 208);
      return;
    }
    const nw = image.naturalWidth || image.width;
    const nh = image.naturalHeight || image.height;
    const splitY = stage.mapSplitY ?? 508;
    const splitSourceY = clamp(Math.floor(nh * (stage.mapSplitSourceRatio ?? 0.54)), 1, nh - 1);
    this.drawFinaleTiledImageCrop(image, 0, 0, nw, splitSourceY, 0, splitY, this.finaleCameraX || 0, stage.backgroundParallax ?? 0.32, 1);
    this.ctx.fillStyle = "rgba(3, 7, 13, 0.18)";
    this.ctx.fillRect(0, 0, VIEW_W, splitY);
    this.drawFinaleTiledImageCrop(image, 0, splitSourceY, nw, nh - splitSourceY, splitY, VIEW_H - splitY, this.finaleCameraX || 0, stage.foregroundParallax ?? 1, 1);
    this.ctx.fillStyle = "rgba(255, 205, 116, 0.06)";
    for (let x = -160 - ((this.finaleCameraX || 0) % 240); x < VIEW_W + 240; x += 240) {
      this.ctx.fillRect(Math.round(x), splitY + 14, 72, 3);
    }
  }

  drawFinaleTiledImageCrop(image, sx, sy, sw, sh, dy, dh, cameraX, parallaxFactor = 1, alpha = 1) {
    if (!image || !sw || !sh || !dh) return false;
    const scale = dh / sh;
    const drawW = sw * scale;
    const offset = cameraX * parallaxFactor;
    const firstTile = Math.floor(offset / drawW) - 1;
    const lastTile = Math.ceil((offset + VIEW_W) / drawW) + 1;
    this.ctx.save();
    this.ctx.globalAlpha *= alpha;
    for (let tile = firstTile; tile <= lastTile; tile += 1) {
      const x = Math.round(tile * drawW - offset);
      this.ctx.drawImage(image, sx, sy, sw, sh, x, dy, Math.ceil(drawW), dh);
    }
    this.ctx.restore();
    return true;
  }

  getFinalePrompt() {
    if (this.isFinaleNearGanGan()) {
      return { text: this.tr("O TALK TO GAN GAN", "O 跟 Gan Gan 說話"), color: "#ffd36c" };
    }
    return { text: this.tr("◀ ▶ MOVE   O TALK", "◀ ▶ 移動   O 互動"), color: "#8fe8ff" };
  }

  drawFinaleBobby(frozen = false) {
    if (!this.finale?.player) return;
    const stage = this.getFinaleStageConfig();
    const player = this.finale.player;
    const bobby = {
      ...player,
      x: Math.round(player.x - (this.finaleCameraX || 0)),
      y: player.y ?? stage.floorY,
      mounted: false,
      depthV: 0,
      scale: stage.playerScale ?? player.scale ?? 0.92,
      floorY: stage.floorY ?? player.y
    };
    const outfitSpec = { ...this.config.sprites.bobby, onFoot: this.getEquippedBobbyFootSpec() };
    drawBobby(this.ctx, bobby, this.time, frozen, this.getEquippedBobbyRefs(), outfitSpec);
  }

