  renderPocketContent(rect) {
    this.ctx.save();
    this.ctx.textAlign = "left";
    this.ctx.textBaseline = "top";
    this.ctx.fillStyle = "#3a4126";
    drawFittedText(this.ctx, `POCKET · ${this.pocketTab.toUpperCase()}`, rect.x + 24, rect.y + 18, 250, 18, 900, 13);
    if (this.hotbarAssignIndex !== null && this.hotbarAssignIndex !== undefined) {
      this.ctx.textAlign = "right";
      this.ctx.fillStyle = "#a03418";
      drawFittedText(
        this.ctx,
        `SELECT ITEM FOR SLOT ${this.hotbarAssignIndex + 1}`,
        rect.x + rect.w - 24,
        rect.y + 19,
        300,
        16,
        900,
        11
      );
      this.ctx.textAlign = "left";
    }
    this.ctx.font = "900 26px 'Courier New', 'PingFang TC', 'Noto Sans TC', monospace";
    this.ctx.fillStyle = "#3a4126";

    const layout = this.getPocketScrollLayout();
    const scroll = layout.scroll;
    const pocketItems = this.normalizePocketSelection();
    const selectedIndex = pocketItems.length ? this.pocketSelectedIndex : -1;
    const clipList = (drawRows) => {
      this.ctx.save();
      this.ctx.beginPath();
      this.ctx.rect(layout.viewport.x, layout.viewport.y, layout.viewport.w, layout.viewport.h);
      this.ctx.clip();
      drawRows();
      this.ctx.restore();
      if (layout.maxScroll > 0) {
        this.ctx.fillStyle = "rgba(58, 65, 38, 0.22)";
        this.ctx.fillRect(layout.track.x, layout.track.y, layout.track.w, layout.track.h);
        this.ctx.strokeStyle = "#5a6338";
        this.ctx.lineWidth = 2;
        this.ctx.strokeRect(layout.track.x + 1, layout.track.y + 1, layout.track.w - 2, layout.track.h - 2);
        this.ctx.fillStyle = "#3a4126";
        this.ctx.fillRect(layout.thumb.x, layout.thumb.y, layout.thumb.w, layout.thumb.h);
      }
    };

    if (this.pocketTab === "Props") {
      const propIds = this.getPocketPropIds();
      if (!propIds.length) {
        this.ctx.fillText("EMPTY", rect.x + 28, rect.y + 76);
      } else {
        clipList(() => {
          propIds.forEach((itemId, index) => {
            const row = getPocketInventoryItemRect(index, scroll);
            drawPocketInventoryRow(this.ctx, row, itemId, this.inventory?.[itemId] || 0, this.refs.level2BundleSheet, this.config?.sprites?.level2Bundle);
            if (index === selectedIndex) drawPocketSelectionFrame(this.ctx, row);
          });
          drawPocketSmallText(this.ctx, "Click a bottle to use it.", layout.viewport.x + 20, layout.viewport.y + 16 + propIds.length * 70 - scroll, "#3a4126", layout.viewport.w - 40);
        });
      }
    } else if (this.pocketTab === "Weapons") {
      const weaponIds = this.getPocketWeaponIds();
      if (!weaponIds.length) {
        this.ctx.fillText("EMPTY", rect.x + 28, rect.y + 76);
      } else {
        clipList(() => {
          weaponIds.forEach((weaponId, index) => {
            const row = getPocketWeaponRect(index, scroll);
            drawPocketWeaponRow(this.ctx, row, weaponId, true, this.inventory?.equippedWeapon === weaponId, this.refs.level2BundleSheet, this.config?.sprites?.level2Bundle);
            if (index === selectedIndex) drawPocketSelectionFrame(this.ctx, row);
          });
          const help = this.inventory?.equippedWeapon === "bugSpray"
            ? "H: spray weapon    M: disabled while weapon is equipped"
            : "Click a weapon to equip it.";
          drawPocketSmallText(this.ctx, help, layout.viewport.x + 20, layout.viewport.y + 16 + weaponIds.length * 70 - scroll, "#3a4126", layout.viewport.w - 40);
        });
      }
    } else if (this.pocketTab === "Outfits") {
      const equipped = this.getEquippedOutfitId();
      const outfitIds = this.getPocketOutfitIds();
      if (!outfitIds.length) {
        this.ctx.fillText("EMPTY", rect.x + 28, rect.y + 76);
      } else {
        clipList(() => {
          outfitIds.forEach((outfitId, index) => {
            const row = getPocketOutfitRect(index, scroll);
            drawPocketOutfitRow(
              this.ctx,
              row,
              outfitId,
              true,
              equipped === outfitId,
              this.getOutfitPreviewSheet(outfitId),
              this.getOutfitPreviewSpec(outfitId)
            );
            if (index === selectedIndex) drawPocketSelectionFrame(this.ctx, row);
          });
          drawPocketSmallText(this.ctx, "Click to equip. Drag outfits to the item bar.", layout.viewport.x + 20, layout.viewport.y + 12 + outfitIds.length * 42 - scroll, "#3a4126", layout.viewport.w - 40);
        });
      }
    } else if (this.pocketTab === "Songs") {
      const songs = this.getCollectedSongDefs();
      if (!songs.length) {
        this.ctx.fillText("NO SONGS", rect.x + 28, rect.y + 76);
        drawPocketSmallText(this.ctx, "Complete levels to collect their background music.", rect.x + 28, rect.y + 118, "#3a4126", rect.w - 56);
      } else {
        clipList(() => {
          songs.forEach((song, index) => {
            const row = getPocketSongRect(index, scroll);
            drawPocketSongRow(this.ctx, row, song, this.songPreview?.id === song.id);
            if (index === selectedIndex) drawPocketSelectionFrame(this.ctx, row);
          });
        });
      }
    } else {
      const button = getPocketSaveButtonRect();
      drawPocketSaveButton(this.ctx, button);
      if (selectedIndex === 0) drawPocketSelectionFrame(this.ctx, button);
      this.ctx.font = "900 18px 'Courier New', 'PingFang TC', 'Noto Sans TC', monospace";
      this.ctx.fillStyle = "#e8edc4";
      this.ctx.fillText(this.tr("SAVE PROGRESS", "儲存進度  SAVE"), button.x + 22, button.y + 14);
      const saveText = this.savedGame?.savedAt
        ? `LAST SAVE  ${formatSavedTime(this.savedGame.savedAt)}`
        : "NO SAVE DATA";
      drawPocketSmallText(this.ctx, saveText, rect.x + 26, rect.y + 104, "#3a4126", rect.w - 52);
      this.ctx.fillStyle = "#a03418";
      drawFittedText(this.ctx, this.tr("SAVE BEFORE LEAVING OR YOU WILL LOSE YOUR PROGRESS.", "提醒：離開前請先儲存，否則目前進度將全部遺失！"), rect.x + 26, rect.y + 130, rect.w - 52, 16, 900, 11);
      const homeButton = getPocketHomeButtonRect();
      drawPocketHomeButton(this.ctx, homeButton);
      if (selectedIndex === 1) drawPocketSelectionFrame(this.ctx, homeButton);
    }
    this.ctx.restore();
  }

